// Generated from src/registry/sources/control-ui/recipes/phone-input.css by scripts/gen-knob-contracts.ts — run `bun run sync:knobs`.
export const phoneInputKnobs = [
  "--cui-phone-input-country-border-color",
  "--cui-phone-input-country-border-width",
  "--cui-phone-input-trigger-hover-background",
  "--cui-phone-input-trigger-focus-background",
  "--cui-phone-input-metadata-foreground",
  "--cui-phone-input-chevron-foreground",
] as const;
export type PhoneInputKnobStyle = Partial<Record<(typeof phoneInputKnobs)[number], string>>;

import { AsYouType } from "libphonenumber-js/max";
import { type Country, getCountryCallingCode, type Value } from "react-phone-number-input/max";

export function normalizePhoneInputText(value: string, country: Country | undefined) {
  if (!country) return value;

  const callingCode = `+${getCountryCallingCode(country)}`;
  if (!value.startsWith(callingCode)) return value;

  const nationalDigits = value.slice(callingCode.length).replaceAll(/\D/g, "");
  if (!nationalDigits) return value;

  const nationalFormatter = new AsYouType(country);
  nationalFormatter.input(nationalDigits);
  const normalizedValue = nationalFormatter.getNumberValue();
  return normalizedValue ? new AsYouType().input(normalizedValue) : value;
}

export function normalizePhoneInputValue(value: Value | undefined, country: Country | undefined) {
  if (!value || !country) return value;

  const callingCode = `+${getCountryCallingCode(country)}`;
  if (!value.startsWith(callingCode)) return value;

  const nationalDigits = value.slice(callingCode.length);
  if (!nationalDigits) return value;

  const formatter = new AsYouType(country);
  formatter.input(nationalDigits);
  return formatter.getNumberValue();
}

import { isPossiblePhoneNumber, isValidPhoneNumber, type Value as PhoneInputValue, parsePhoneNumber } from "react-phone-number-input/max";
import { e164 } from "zod";

export type PhoneNumberValidationMode = "possible" | "valid";

export type PhoneNumberSchemaMessages = {
  format?: string;
  invalid?: string;
  mobile?: string;
};

export type PhoneNumberSchemaOptions = {
  mode?: PhoneNumberValidationMode;
  mobileOnly?: boolean;
  messages?: PhoneNumberSchemaMessages;
};

const DEFAULT_MESSAGES = {
  format: "Enter a phone number in international format.",
  invalid: "Enter a valid phone number.",
  mobile: "Enter a mobile phone number.",
} as const;

const MOBILE_TYPES = new Set(["MOBILE", "FIXED_LINE_OR_MOBILE"]);

function isMobilePhoneNumber(value: string) {
  try {
    const type = parsePhoneNumber(value)?.getType();
    return type ? MOBILE_TYPES.has(type) : false;
  } catch {
    return false;
  }
}

export function createPhoneNumberSchema({ mode = "valid", mobileOnly = false, messages = {} }: PhoneNumberSchemaOptions = {}) {
  const isAccepted = mode === "possible" ? isPossiblePhoneNumber : isValidPhoneNumber;

  let schema = e164(messages.format ?? DEFAULT_MESSAGES.format).refine(isAccepted, messages.invalid ?? DEFAULT_MESSAGES.invalid);

  if (mobileOnly) {
    schema = schema.refine(isMobilePhoneNumber, messages.mobile ?? DEFAULT_MESSAGES.mobile);
  }

  return schema.transform((value): PhoneInputValue => value);
}

export const phoneNumberSchema = createPhoneNumberSchema();
export const possiblePhoneNumberSchema = createPhoneNumberSchema({ mode: "possible" });
export const mobilePhoneNumberSchema = createPhoneNumberSchema({ mobileOnly: true });

@layer components {
  :where([data-control-family="field"][data-field-kind="phone-input"][data-slot="root"]) {
    --cui-phone-input-country-border-color: var(--border);
    --cui-phone-input-country-border-width: var(--control-rim-width);
    --cui-phone-input-trigger-hover-background: var(--hover-fill);
    --cui-phone-input-trigger-focus-background: var(--hover-fill);
    --cui-phone-input-metadata-foreground: var(--muted-foreground);
    --cui-phone-input-chevron-foreground: var(--muted-foreground);
  }

  :where([data-control-family="phone-input"][data-slot="root"]) {
    --cui-phone-input-metadata-foreground: var(--muted-foreground);
  }

  :where([data-control-family="field"][data-phone-input-country]) {
    border-inline-end: var(--cui-phone-input-country-border-width) solid var(--cui-phone-input-country-border-color);
  }

  @media (hover: hover) {
    :where([data-control-family="phone-input"][data-slot="country-trigger"]:hover:not(:disabled)) {
      background-color: var(--cui-phone-input-trigger-hover-background);
    }
  }

  :where([data-control-family="phone-input"][data-slot="country-trigger"]:focus-visible) {
    background-color: var(--cui-phone-input-trigger-focus-background);
  }

  :where([data-control-family="phone-input"][data-slot="flag"]) {
    inline-size: calc(var(--spacing) * 5);
    block-size: calc(var(--spacing) * 3.5);
    border-radius: min(var(--radius-sm), 2px);
    color: var(--muted-foreground);
  }

  :where([data-control-family="phone-input"][data-slot="metadata"]) {
    color: var(--cui-phone-input-metadata-foreground);
    font-size: var(--text-caption);
    font-variant-numeric: tabular-nums;
  }

  :where([data-control-family="phone-input"][data-slot="country-code"]) {
    color: currentColor;
    font-size: var(--text-caption);
  }

  :where([data-control-family="phone-input"][data-slot="chevron"]) {
    --_phone-input-chevron-rotate: 0deg;
    inline-size: calc(var(--spacing) * 3);
    block-size: calc(var(--spacing) * 3);
    color: var(--cui-phone-input-chevron-foreground);
    transition-property: transform, translate, scale, rotate;
    transition-duration: var(--duration-base);
    rotate: var(--_phone-input-chevron-rotate);
    transition-timing-function: var(--ease-emphasized);
  }

  :where([data-control-family="phone-input"][data-slot="chevron"][data-open]) {
    --_phone-input-chevron-rotate: 180deg;
  }

  :where([data-control-family="phone-input"][data-slot="check"]) {
    inline-size: calc(var(--spacing) * 3.5);
    block-size: calc(var(--spacing) * 3.5);
  }

  :where([data-control-family="phone-input"][data-slot="check"] > svg) {
    inline-size: calc(var(--spacing) * 3);
    block-size: calc(var(--spacing) * 3);
  }

  :where([data-control-family="phone-input"][data-slot="check"]:not([data-visible])) {
    opacity: 0;
  }

  :where([data-control-family="phone-input"][data-slot="country-trigger"]) {
    min-inline-size: calc(var(--spacing) * 14);
    gap: calc(var(--spacing) * 2);
    padding-inline: calc(var(--spacing) * 3);
    cursor: pointer;
  }

  :where([data-control-family="phone-input"][data-slot="country-trigger"]:disabled) {
    cursor: not-allowed;
  }

  :where(
    [data-control-family="phone-input"][data-slot="country-trigger"]:disabled:not(
      [data-control-family="field"][data-control="true"][data-disabled] *
    )
  ) {
    opacity: var(--disabled-opacity);
  }

  :where(
    [data-control-family="field"][data-field-kind="phone-input"][data-slot="root"]
      [data-control-family="field"][data-field-kind="input-group"][data-slot="input"]
  ) {
    padding-inline: calc(var(--spacing) * 3);
    font-variant-numeric: tabular-nums;
  }
}

